import Foundation
import XCTest
@testable import SO101Protocol

/// The fixtures are generated by robot/tests/test_protocol_fixtures.py, so these tests
/// prove Swift and Python agree on every byte that matters.
final class ContractTests: XCTestCase {
    private func fixture(_ name: String) throws -> Data {
        let url = try XCTUnwrap(Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures"))
        return try Data(contentsOf: url)
    }

    private func object(_ data: Data) throws -> NSDictionary {
        try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? NSDictionary)
    }

    private func assertEncodes<T: TypedMessage>(_ message: T, like name: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let ours = try object(ProtocolCoder.encode(message))
        let theirs = try object(fixture(name))
        XCTAssertEqual(ours, theirs, "Swift encoding of \(T.self) drifted from \(name).json", file: file, line: line)
    }

    // MARK: Phone -> Agent: Swift must produce exactly what Python parses.

    func testWatchMotion() throws {
        try assertEncodes(WatchMotion(sessionId: "s-1021", seq: 912, sampleMonoNs: 18_391_239_123,
                                      quaternionWxyz: [0.99, 0.01, -0.12, 0.04], gyroRadS: [0.02, 0.01, -0.03],
                                      gravityG: [0.03, -0.04, -0.998], controlEpoch: 14),
                          like: "watch_motion")
    }

    func testWatchLifecycle() throws {
        try assertEncodes(WatchLifecycle(sessionId: "s-1021", seq: 3, state: .inactive), like: "watch_lifecycle")
    }

    func testControlIntent() throws {
        try assertEncodes(ControlIntent(requestId: "c-5394", sessionId: "s-1021", controlEpoch: 14,
                                        intent: .doubleTap, source: "watch-primary-action"),
                          like: "control_intent")
    }

    func testVoiceTranscript() throws {
        try assertEncodes(VoiceTranscript(requestId: "v-77", sessionId: "s-1021", controlEpoch: 16, text: "把紅色積木放進盒子"),
                          like: "voice_transcript")
    }

    func testVoiceTranscriptNullIsExplicit() throws {
        let msg = VoiceTranscript(requestId: "v-78", sessionId: "s-1021", controlEpoch: 16, text: nil)
        try assertEncodes(msg, like: "voice_transcript_null")
        XCTAssertTrue(try object(ProtocolCoder.encode(msg))["text"] is NSNull)
    }

    // MARK: Agent -> Phone: Swift must decode everything Python sends.

    func testHapticEvent() throws {
        guard case .haptic(let ev) = try ProtocolCoder.decodeFromAgent(fixture("haptic_event")) else {
            return XCTFail("not a haptic event")
        }
        XCTAssertEqual(ev.kind, .limitHit)
        XCTAssertEqual(ev.axis, "shoulder_pan")
        XCTAssertEqual(ev.limitType, "soft_joint")
        XCTAssertTrue(ev.playHaptic)
        XCTAssertNil(ev.transactionId)
        XCTAssertEqual(ev.ttlMs, 500)
    }

    func testGraspEvent() throws {
        guard case .haptic(let ev) = try ProtocolCoder.decodeFromAgent(fixture("haptic_event_grasp")) else {
            return XCTFail("not a haptic event")
        }
        XCTAssertEqual(ev.kind, .graspLikely)
        XCTAssertEqual(ev.transactionId, 3)
        XCTAssertEqual(ev.evidence, ["position_stall", "current_delta"])
        XCTAssertFalse(ev.playHaptic)
        XCTAssertLessThan(ev.confidence, 1.0)
    }

    func testRobotStatus() throws {
        guard case .status(let s) = try ProtocolCoder.decodeFromAgent(fixture("robot_status")) else {
            return XCTFail("not a status")
        }
        XCTAssertEqual(s.mode, .awaitRecalibration)
        XCTAssertEqual(s.owner, Owner.none)
        XCTAssertEqual(s.controlEpoch, 15)
        XCTAssertEqual(s.vlaTaskId, "pick_red_cube_into_box")
        XCTAssertTrue(s.robotHolding)
    }

    func testControlAck() throws {
        guard case .ack(let a) = try ProtocolCoder.decodeFromAgent(fixture("control_ack")) else {
            return XCTFail("not an ack")
        }
        XCTAssertEqual(a.result, .rejected)
        XCTAssertEqual(a.reason, "STALE_EPOCH")
    }

    func testError() throws {
        XCTAssertEqual(try ProtocolCoder.decodeFromAgent(fixture("error")),
                       .error(ErrorMessage(reason: "unknown message type 'x'")))
    }

    func testUnknownTypeAndWrongVersion() throws {
        let unknown = Data(#"{"protocol_version":1,"type":"robot.future_thing"}"#.utf8)
        XCTAssertEqual(try ProtocolCoder.decodeFromAgent(unknown), .unknown(type: "robot.future_thing"))
        let v2 = Data(#"{"protocol_version":2,"type":"robot.status"}"#.utf8)
        XCTAssertThrowsError(try ProtocolCoder.decodeFromAgent(v2)) {
            XCTAssertEqual($0 as? ProtocolError, .unsupportedVersion(2))
        }
    }
}
